SELECT inventory.id, inventory.quantity, inventory.product_id, store_sales.sale_date, store_sales.units, ROUND(store_sales.revenue / store_sales.units, 2) AS revenue_per_unit FROM inventory LEFT JOIN store_sales ON inventory.store_id = store_sales.store_id AND inventory.product_id = store_sales.product_id WHERE inventory.store_id = 1 AND store_sales.product_id IN (3, 10) ORDER BY revenue_per_unit DESC, store_sales.units DESC;
